}

let parsePostRow (row: obj) : PostRow =
    { Id = rowStr row "id"
      Title = rowStr row "title"
      Body = rowStr row "body"
      CreatedAt = rowInt row "created_at" }

let selectPosts (db: D1Database) : D1PreparedStatement =
    db.prepare("SELECT id, title, body, created_at FROM posts ORDER BY created_at DESC LIMIT 100")

let selectPost (id: string) (db: D1Database) : D1PreparedStatement =
    bind (db.prepare("SELECT id, title, body, created_at FROM posts WHERE id = ?")) [| box id |]

let insertPost (db: D1Database) (id: string) (now: int) (create: PostCreate) =
    let stmt =
        bind (db.prepare("INSERT INTO posts (id, title, body, created_at) VALUES (?, ?, ?, ?)"))
             [| box id; box create.Title; box create.Body; box now |]
    {| Stmt = stmt; Id = id; CreatedAt = now |}

let updatePost (id: string) (create: PostCreate) (db: D1Database) : D1PreparedStatement =
    bind (db.prepare("UPDATE posts SET title = ?, body = ? WHERE id = ?"))
         [| box create.Title; box create.Body; box id |]

let deletePost (id: string) (db: D1Database) : D1PreparedStatement =
    bind (db.prepare("DELETE FROM posts WHERE id = ?")) [| box id |]

